import RNA
tgt=open('/tmp/tgt400.txt').read().strip()
pair=[None]*len(tgt)
st=[]
for i,c in enumerate(tgt):
    if c=='(': st.append(i)
    elif c==')':
        j=st.pop(); pair[i]=j; pair[j]=i
out=[]
for i,c in enumerate(tgt):
    if c=='.':
        out.append('A')
    else:
        if i<pair[i]:
            out.append('G')
        else:
            out.append('C')
seq=''.join(out)
fc=RNA.fold_compound(seq)
mfe,e=fc.mfe()
dist=RNA.bp_distance(mfe,tgt)
print('len',len(seq),'mfe==tgt',mfe==tgt,'bpdist',dist)
print(seq)

