    elif c==')':
        j=st.pop(); pair[i]=j; pair[j]=i
opens=[i for i,c in enumerate(tgt) if c=='(']
segs=[]; k=0
while k<len(opens):
    grp=[opens[k]]
    while k+1<len(opens) and opens[k+1]==opens[k]+1:
        k+=1; grp.append(opens[k])
    k+=1; segs.append(grp)
FAM=[('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')]
def build(famseq):
    out=['A']*len(tgt)
    for si,grp in enumerate(segs):
        f=FAM[famseq[si]]; 
        for pos in grp:
            out[pos]=f[0]; out[pair[pos]]=f[1]
    return ''.join(out)
def score(famseq):
    seq=build(famseq)
    fc=RNA.fold_compound(seq); mfe,e=fc.mfe()
    return RNA.bp_distance(mfe,tgt),seq
random.seed(42)
nseg=len(segs)
best_overall=(999,None,None)
for restart in range(6):
    fam=[random.randrange(6) for _ in range(nseg)]
    cur_d,cur_seq=score(fam)
    improved=True
    while improved:
        improved=False
        for si in range(nseg):
            for nf in range(6):
                if nf==fam[si]: continue
                old=fam[si]; fam[si]=nf
